/// The wire error code the tag APIs (`TagResource`, `ListTagsForResource`,
/// `UntagResource`) answer for a `resourceArn` naming no resource of this account.
///
/// The recorded responses of those operations carry `NotFoundException`, NOT the
/// `ResourceNotFoundException` their model lists — the tag APIs are fronted by a layer
/// with its own error taxonomy, and a client branching on the code sees that one.
pub const NOT_FOUND_CODE: &str = "NotFoundException";
/// The HTTP status of that refusal.
///
/// 404, not the 400 this service's modeled client errors carry: the refusal reports that
/// the addressed resource is ABSENT, and the recorded responses of the tag APIs answer an
/// unregistered `resourceArn` with 404 — which is what a client branching on the status
/// (create-if-absent, tolerate-missing, retry and alarm classification) reads as "not
/// there" rather than "malformed request". The model says nothing to the contrary: no
/// `@httpError` is attached to the `ResourceNotFoundException` it lists for these
/// operations, so its 400 is only Smithy's default for a client error.
pub const NOT_FOUND_STATUS: u16 = 404;
/// The text that refusal carries: a CONSTANT, naming nothing from the request.
pub const NOT_FOUND_MESSAGE: &str = "Resource was not found";
/// The wire error code the tag APIs answer when a request selects more tags than a
/// resource may carry — the tag set a write would leave on the resource, or the key list
/// a removal names — and when the `resourceArn` they were given cannot be parsed as a
/// resource ARN at all.
pub const BAD_REQUEST_CODE: &str = "BadRequestException";
/// The HTTP status of that refusal.
pub const BAD_REQUEST_STATUS: u16 = 400;
/// The text that refusal carries, naming the limit and nothing from the request — which
/// matters doubly here, because every member a tag selection travels in is `@sensitive`.
///
/// ONE sentence for the whole surface: the limit it states is the size of the tag set a
/// resource may carry (50), and a write's tag map and a removal's key list are both
/// selections out of that one set, so a request naming more than the limit is refused
/// with the same words whichever member carried it.
pub const TAG_LIMIT_MESSAGE: &str = "The resultant tag set must not have more than 50 user tags.";
/// The text the tag APIs' refusal of an unparseable `resourceArn` carries: a CONSTANT,
/// naming neither the member nor the value — which is what distinguishes it from the
/// constraint envelope `crate::service::validation` states for every other member.
pub const INVALID_RESOURCE_ARN_MESSAGE: &str = "Invalid input resource arn: bad syntax";

/// The wire error code the tag APIs answer when the caller may not reach the resource
/// `resourceArn` names at all — a resource field naming an account other than the one this
/// request is served for.
///
/// This service's model declares no shape for an authorization refusal on these operations
/// (`smithy_query(query="operation",operation="TagResource")` lists `InternalServerException`,
/// `ResourceNotFoundException` and `ValidationException`), so the code goes on the wire as
/// the recorded service's own: a client branches on the code, and AWS states this class with
/// the standard IAM denial.
pub const ACCESS_DENIED_CODE: &str = "AccessDeniedException";
/// The HTTP status that refusal carries.
///
/// 403, the status of an authorization failure, which a client reads as a PERMANENT refusal
/// to be surfaced to the operator — as opposed to the 404 of
/// [`NOT_FOUND_STATUS`], which invites a create-then-retry or is swallowed as an idempotent
/// miss.
pub const ACCESS_DENIED_STATUS: u16 = 403;

/// The text `TagResource` refuses a request whose tag map names no pair with: a CONSTANT,
/// with no variable part.
///
/// It is one of the tagging surface's own refusals, so it travels with that surface's
/// [`BAD_REQUEST_CODE`] / [`BAD_REQUEST_STATUS`] rather than with the generic
/// `ValidationException` the operation models: the request itself is wrong, and this surface
/// states every wrong request of its own with that one code (compare
/// [`INVALID_RESOURCE_ARN_MESSAGE`] and [`TAG_LIMIT_MESSAGE`], whose sentences are worded the
/// same way). The model does not express the bound at all:
/// `TagResourceRequest$tags` is `@required` with `@length(min: 0, max: 50)`, so an empty map
/// is model-legal and only the recorded service refuses it.
pub const NON_EMPTY_TAGS_MESSAGE: &str = "Invalid request input, expected non-empty tags map";

/// One refusal this service states with an error code its model does not declare.
///
/// It carries its own wire code, HTTP status and message precisely because the shape is
/// not in the model, so there is no `#[operation_error]` variant that could render it.
/// The four this service states are [`not_found`](Self::not_found) (HTTP 404
/// `NotFoundException`), [`access_denied`](Self::access_denied) (HTTP 403
/// `AccessDeniedException`), [`tag_limit_exceeded`](Self::tag_limit_exceeded) and
/// [`invalid_resource_arn`](Self::invalid_resource_arn) (HTTP 400
/// `BadRequestException`).
///
/// The message is a [`Cow`] because most of these refusals are CONSTANT text — they name
/// nothing from the request, which is what keeps a sensitive tag selection and an ARN out of
/// them — while the authorization denial has one variable part, the calling principal, which
/// is server-derived rather than taken from the request.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct UnmodeledRefusal {
    /// The wire error code (`__type`, and `x-amzn-errortype` where the protocol sets it).
    pub code: &'static str,
    /// The HTTP status.
    pub status: u16,
    /// The message this refusal carries.
    pub message: Cow<'static, str>,
}

impl UnmodeledRefusal {
    /// The tag APIs' refusal of a `resourceArn` that addresses no resource of this
    /// account: HTTP 404 `NotFoundException`.
    pub const fn not_found() -> Self {
        Self {
            code: NOT_FOUND_CODE,
            status: NOT_FOUND_STATUS,
            message: Cow::Borrowed(NOT_FOUND_MESSAGE),
        }
    }

    /// The tag APIs' refusal of a `resourceArn` the caller may not reach at all: HTTP 403
    /// `AccessDeniedException`, naming `principal` — the identity whose authorization was
    /// evaluated — and nothing about what it asked for.
    pub fn access_denied(principal: &str) -> Self {
        Self {
            code: ACCESS_DENIED_CODE,
            status: ACCESS_DENIED_STATUS,
            message: Cow::Owned(
                ::service_common::iam_authorization::not_authorized_to_access_resource(principal),
            ),
        }
    }

    /// The tag APIs' refusal of a request selecting more tags than a resource may carry —
    /// a write whose resultant tag set would be over the limit, or a removal naming more
    /// keys than the limit: HTTP 400 `BadRequestException`.
    pub const fn tag_limit_exceeded() -> Self {
        Self {
            code: BAD_REQUEST_CODE,
            status: BAD_REQUEST_STATUS,
            message: Cow::Borrowed(TAG_LIMIT_MESSAGE),
        }
    }

    /// The tag APIs' refusal of a `resourceArn` they cannot parse as a resource ARN:
    /// HTTP 400 `BadRequestException`. The FORMAT stage, ahead of the existence stage
    /// [`not_found`](Self::not_found) answers.
    pub const fn invalid_resource_arn() -> Self {
        Self {
            code: BAD_REQUEST_CODE,
            status: BAD_REQUEST_STATUS,
            message: Cow::Borrowed(INVALID_RESOURCE_ARN_MESSAGE),
        }
    }

    /// The tagging surface's refusal of a tag write whose map names no pair: HTTP 400
    /// `BadRequestException`, stated before the addressed resource is resolved.
    pub const fn non_empty_tags() -> Self {
        Self {
            code: BAD_REQUEST_CODE,
            status: BAD_REQUEST_STATUS,
            message: Cow::Borrowed(NON_EMPTY_TAGS_MESSAGE),
        }
    }
}

impl std::fmt::Display for UnmodeledRefusal {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}: {}", self.code, self.message)
    }
}


impl std::error::Error for UnmodeledRefusal {}

impl SerializableStruct for UnmodeledRefusal {
    fn serialize_members(&self, s: &mut dyn ShapeSerializer) -> Result<(), SerdeError> {
        s.write_string(&UNMODELED_REFUSAL_MESSAGE, self.message.as_ref())?;
        Ok(())
    }
}

/// An operation's error channel: either the synthetic scaffold signal, or one of the
/// operation's own modeled errors.
#[derive(Debug)]
pub enum Scaffolded<E> {
    /// The operation is generated but has no implementation. Renders as HTTP 501.
    NotImplemented(NotImplemented),
    /// A modeled error the operation declares. Renders with the model's own status.
    Modeled(E),
    /// A refusal this service states with a code its model does not declare — so it
    /// cannot travel as [`Modeled`](Self::Modeled). Renders with the status and code the
    /// refusal itself carries.
    Unmodeled(UnmodeledRefusal),
    /// The request was refused as invalid. Renders as HTTP 400 with the error code
    /// `ValidationException`.
    ///
    /// On the JSON and CBOR protocols that is the same status and code the boundary
    /// validator answers with. Two differences are worth knowing, and neither is
    /// specific to this variant — every handler-returned error shares them:
    /// the awsJson families omit the `x-amzn-errortype` header that the boundary
    /// path sets, and the query protocols render a boundary refusal as
    /// `MalformedQueryString` rather than `ValidationException`, so a client
    /// matching on the error code there sees two codes for one logical failure.
    ValidationException(ValidationException),
}

impl<E> Scaffolded<E> {
    /// The scaffold signal for `operation`.
    pub fn not_implemented(operation: &str) -> Self {
        Self::NotImplemented(NotImplemented::new(operation))
    }

    /// Refuse the request the way the tag APIs refuse a `resourceArn` that addresses no
    /// resource of this account: HTTP 404 `NotFoundException`.
    pub const fn not_found() -> Self {
        Self::Unmodeled(UnmodeledRefusal::not_found())
    }

    /// Refuse the request the way the tag APIs refuse a `resourceArn` the caller may not
    /// reach at all: HTTP 403 `AccessDeniedException`, naming `principal`.
    ///
    /// Reached through `crate::service::authorization`, which is where the verdict itself
    /// lives; this constructor is only how it is WORDED.
    pub fn access_denied(principal: &str) -> Self {
        Self::Unmodeled(UnmodeledRefusal::access_denied(principal))
    }

    /// Refuse a tag request selecting more tags than a resource may carry — a write whose
    /// resultant tag set would be over the limit, or a removal naming more keys than the
    /// limit: HTTP 400 `BadRequestException`.
    pub const fn tag_limit_exceeded() -> Self {
        Self::Unmodeled(UnmodeledRefusal::tag_limit_exceeded())
    }

    /// Refuse a tag write whose map names no pair, the way the tagging surface refuses it:
    /// HTTP 400 `BadRequestException`, before the addressed resource is resolved.
    pub const fn non_empty_tags() -> Self {
        Self::Unmodeled(UnmodeledRefusal::non_empty_tags())
    }

    /// Refuse the request as invalid, with HTTP 400 `ValidationException`.
    ///
    /// Reach for this when the request is wrong in a way the model cannot express,
    /// so the boundary validator passed it: a value outside a rule the service
    /// enforces but does not model, or a combination of members that cannot hold
    /// together. Answer it INSTEAD of `not_implemented` — a 501 says "nobody has
    /// written this yet", which is a different claim and is counted as one.
    ///
    /// If this service's model declares its own `ValidationException` (or another
    /// client-input error) use THAT: the modeled shape may carry members beyond
    /// `message` — a `reason`, a field list — and a real client reads them. When the
    /// operation already lists it, it is a plain variant on the generated error enum;
    /// `#[operation_error]`'s `extra_errors` is only for widening in a shape the
    /// SERVICE models that this OPERATION does not list.
    pub fn validation(message: impl Into<String>) -> Self {
        Self::ValidationException(ValidationException::new(message))
    }

    /// Refuse the request the way the tag APIs refuse a `resourceArn` they cannot parse
    /// as a resource ARN: HTTP 400 `BadRequestException`, the FORMAT stage ahead of the
    /// existence stage [`not_found`](Self::not_found) answers.
    ///
    /// Every value this service's tag APIs cannot parse is outside the modelled
    /// `@pattern` on their `resourceArn` label, so the refusal is reached at the request
    /// boundary (`crate::service::validation`) rather than from a handler; this
    /// constructor is what a tag operation would use if it ever had to state the same
    /// refusal after the boundary passed a value it still cannot address.
    pub const fn invalid_resource_arn() -> Self {
        Self::Unmodeled(UnmodeledRefusal::invalid_resource_arn())
    }
}

impl<E: std::fmt::Display> std::fmt::Display for Scaffolded<E> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::NotImplemented(e) => write!(f, "{e}"),
            Self::Modeled(e) => write!(f, "{e}"),
            Self::Unmodeled(e) => write!(f, "{e}"),
            Self::ValidationException(e) => write!(f, "{e}"),
        }
    }
}

/// `source()` forwards to the modeled error rather than taking the default `None`, so a
/// modeled error's own `source()` is preserved through the wrapper.
impl<E: std::error::Error + 'static> std::error::Error for Scaffolded<E> {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::NotImplemented(e) => e.source(),
            Self::Modeled(e) => e.source(),
            Self::Unmodeled(e) => e.source(),
            Self::ValidationException(e) => e.source(),
        }
    }
}

/// Every `OperationError` method delegates to the modeled error, so wrapping an
/// implemented operation's error channel changes NOTHING about how that error is
/// rendered. Only the synthetic variant behaves differently — and it is the one that
/// must answer 501.
impl<E: OperationError> OperationError for Scaffolded<E> {
    fn as_serializable(&self) -> &dyn SerializableStruct {
        match self {
            Self::NotImplemented(e) => e,
            Self::Modeled(e) => e.as_serializable(),
            Self::Unmodeled(e) => e,
            Self::ValidationException(e) => e,
        }
    }

    fn variant_schema(&self) -> &'static Schema {
        match self {
            Self::NotImplemented(_) => &NOT_IMPLEMENTED_SCHEMA,
            Self::Modeled(e) => e.variant_schema(),
            Self::Unmodeled(_) => &UNMODELED_REFUSAL_SCHEMA,
            Self::ValidationException(_) => &VALIDATION_EXCEPTION_SCHEMA,
        }
    }

    /// The wire error code (`__type` on JSON/CBOR, `<Code>` on XML).
    ///
    /// Keep the literal as it is: changing it changes the wire error code clients match
    /// on. It is intentionally not tied to the Rust variant name.
    fn shape_name(&self) -> &'static str {
        match self {
            Self::NotImplemented(_) => "NotImplemented",
            Self::Modeled(e) => e.shape_name(),
            // The code the refusal itself carries: this service's tag APIs answer
            // `NotFoundException` / `BadRequestException`, neither of which is a shape
            // its model declares.
            Self::Unmodeled(e) => e.code,
            Self::ValidationException(_) => "ValidationException",
        }
    }

    /// 501 for the scaffold signal.
    ///
    /// Keep it 501 and not a 5xx server fault: SDK retry classifiers treat those as
    /// retryable, so a client would retry an operation that can never succeed.
    fn http_status(&self) -> u16 {
        match self {
            Self::NotImplemented(_) => 501,
            Self::Modeled(e) => e.http_status(),
            Self::Unmodeled(e) => e.status,
            Self::ValidationException(_) => 400,
        }
    }

    fn query_error_code(&self) -> Option<&'static str> {
        match self {
            // No awsQuery code: the synthetic shape is not in the model, so there is
            // no `awsQueryError` trait to honour. The 501 + `<Code>NotImplemented`
            // envelope carries the signal on the query protocols too.
            Self::NotImplemented(_) => None,
            Self::Modeled(e) => e.query_error_code(),
            // Same reason: the synthetic shape carries no `awsQueryError` trait — and
            // this service is restJson1, which has no query envelope at all.
            Self::Unmodeled(_) => None,
            Self::ValidationException(_) => None,
        }
    }
}
